"""Regenerates src/Dispatch.App/Resources/Strings.Designer.cs from Strings.resx.

Run after adding or renaming a string:  python -I tools/gen-strings.py
(Visual Studio users can instead rely on the ResX designer; the output is equivalent.)
"""
import pathlib
import xml.etree.ElementTree as ET

root = pathlib.Path(__file__).resolve().parent.parent
resx = root / "src" / "Dispatch.App" / "Resources" / "Strings.resx"
out = resx.with_name("Strings.Designer.cs")
names = [d.get("name") for d in ET.parse(resx).getroot().findall("data")]
lines = [
    "// <auto-generated>Generated by tools/gen-strings.py from Strings.resx. Do not edit by hand.</auto-generated>",
    "#nullable enable",
    "namespace Dispatch.App.Resources;",
    "",
    "/// <summary>Strongly typed access to the UI strings in Strings.resx (used from XAML via x:Static).</summary>",
    "public static class Strings",
    "{",
    "    private static readonly System.Resources.ResourceManager Manager =",
    "        new(\"Dispatch.App.Resources.Strings\", typeof(Strings).Assembly);",
    "",
    "    public static System.Globalization.CultureInfo? Culture { get; set; }",
    "",
    "    private static string Get(string name) => Manager.GetString(name, Culture) ?? name;",
]
for n in names:
    lines += ["", f"    public static string {n} => Get(nameof({n}));"]
lines.append("}")
out.write_text("\r\n".join(lines) + "\r\n", encoding="utf-8")
print(f"{len(names)} strings -> {out.relative_to(root)}")
